package com.gorsok.toolkitexporter;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.NPCComposition;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;

/** Reads the Quest table from the running game client. Must be used on the client thread. */
final class ClientQuestSource implements GameQuestData.Source
{
	private final Client client;

	ClientQuestSource(Client client)
	{
		this.client = client;
	}

	@Override
	public List<Integer> rows()
	{
		try
		{
			return client.getDBTableRows(DBTableID.Quest.ID);
		}
		catch (RuntimeException e)
		{
			return null; // the table is not loaded (yet)
		}
	}

	@Override
	public Object[] field(int row, int column, int tuple)
	{
		try
		{
			return client.getDBTableField(row, column, tuple);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	@Override
	public String npcName(int npcId)
	{
		try
		{
			NPCComposition npc = client.getNpcDefinition(npcId);
			return npc == null ? null : npc.getName();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	@Override
	public String skillName(int skillId)
	{
		// The game's skill ids follow the order of RuneLite's Skill enum (0 Attack ... 23 Sailing).
		Skill[] skills = Skill.values();
		return skillId >= 0 && skillId < skills.length && isSkill(skills[skillId]) ? skills[skillId].getName() : null;
	}

	/**
	 * Older RuneLite versions listed "Overall" as the last Skill constant; it is not a skill. In RuneLite 1.13 it is no
	 * longer in Skill.values() (and Sailing is the last skill), so nothing may be dropped by position.
	 */
	static boolean isSkill(Skill skill)
	{
		return skill != null && !"Overall".equalsIgnoreCase(skill.getName());
	}
}

package com.gorsok.toolkitexporter;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.DBTableID;

/**
 * Turns the game's own "Quest" database table into a plain, documented structure.
 *
 * The client already holds this table (net.runelite.api.gameval.DBTableID.Quest): for every quest the levels and
 * quests required, the starting tile and NPC, the experience rewarded, the quest points and a few codes. Nothing
 * here is fetched from anywhere: it is read from the running client, so it always matches the game version.
 *
 * Reading the client is kept out of this class (see {@link Source}) so the decoding can be tested on its own.
 */
final class GameQuestData
{
	static final int FORMAT_VERSION = 1;

	/** What the decoder needs from the game client. */
	interface Source
	{
		/** The row ids of the Quest table, or null when the table is not available. */
		List<Integer> rows();

		/** One part ("tuple") of one cell, or null when it is empty or cannot be read. */
		Object[] field(int row, int column, int tuple);

		/** The name of an NPC, or null when unknown. */
		String npcName(int npcId);

		/** The name of a skill, or null when the id is not a known skill. */
		String skillName(int skillId);
	}

	private GameQuestData()
	{
	}

	static Export decode(Source src, String exportedAt, int clientRevision)
	{
		Export out = new Export();
		out.exported_at = exportedAt;
		out.format_version = FORMAT_VERSION;
		out.client_revision = clientRevision;
		out.source = "game client database table Quest (DBTableID.Quest)";
		out.note = "Read from the game client, not from any website. difficulty_code (0-5) and length_code (0-4) are the "
				+ "game's raw codes. requirement_combat_raw, prerequisite_direct and prerequisite_indirect are raw values "
				+ "whose meaning is not known. release_date_parts are the three raw values of the release date. "
				+ "start.x/y/plane come from the packed start coordinate. required_quests are resolved from row ids. "
				+ "npc_names has null where the game itself names the NPC \"null\". Rows of the table whose name has no "
				+ "letter (placeholders for quests not defined yet) are left out and counted in skipped_placeholder_rows. "
				+ "A skill the client has no name for is written as skill#<id>.";
		out.quests = new ArrayList<>();

		List<Integer> rows = src.rows();
		if (rows == null)
		{
			return out;
		}

		Map<Integer, String> names = new HashMap<>();
		for (int row : rows)
		{
			String name = text(src.field(row, DBTableID.Quest.COL_DISPLAYNAME, 0));
			if (name == null)
			{
				continue;
			}
			if (!hasLetter(name))
			{
				out.skipped_placeholder_rows++; // e.g. a quest called ".": a slot the game has not filled yet
				continue;
			}
			names.put(row, name);
		}

		for (int row : rows)
		{
			String name = names.get(row);
			if (name == null)
			{
				continue; // a row without a name is not a quest we can describe
			}

			Quest q = new Quest();
			q.row_id = row;
			q.quest_id = number(src.field(row, DBTableID.Quest.COL_ID, 0));
			q.name = name;
			q.members = number(src.field(row, DBTableID.Quest.COL_MEMBERS, 0)) != null
					&& number(src.field(row, DBTableID.Quest.COL_MEMBERS, 0)) == 1;
			q.difficulty_code = number(src.field(row, DBTableID.Quest.COL_DIFFICULTY, 0));
			q.length_code = number(src.field(row, DBTableID.Quest.COL_LENGTH, 0));
			q.quest_points = number(src.field(row, DBTableID.Quest.COL_QUESTPOINTS, 0));
			q.series = number(src.field(row, DBTableID.Quest.COL_SERIES, 0));
			q.series_number = number(src.field(row, DBTableID.Quest.COL_SERIESNO, 0));
			q.release_date_parts = new int[]{
				orZero(number(src.field(row, DBTableID.Quest.COL_RELEASEDATE, 0))),
				orZero(number(src.field(row, DBTableID.Quest.COL_RELEASEDATE, 1))),
				orZero(number(src.field(row, DBTableID.Quest.COL_RELEASEDATE, 2)))};

			q.levels = pairs(src, row, DBTableID.Quest.COL_REQUIREMENT_STATS);
			q.recommended_levels = pairs(src, row, DBTableID.Quest.COL_RECOMMENDED_STATS);
			q.required_quest_points = number(src.field(row, DBTableID.Quest.COL_REQUIREMENT_QUESTPOINTS, 0));
			q.requirement_combat_raw = number(src.field(row, DBTableID.Quest.COL_REQUIREMENT_COMBAT, 0));
			q.prerequisite_direct = number(src.field(row, DBTableID.Quest.COL_PREREQUISITE_DIRECT, 0));
			q.prerequisite_indirect = number(src.field(row, DBTableID.Quest.COL_PREREQUISITE_INDIRECT, 0));

			q.required_quest_rows = new ArrayList<>();
			q.required_quests = new ArrayList<>();
			for (int requiredRow : ints(src.field(row, DBTableID.Quest.COL_REQUIREMENT_QUESTS, 0)))
			{
				q.required_quest_rows.add(requiredRow);
				q.required_quests.add(names.get(requiredRow)); // null when the row is unknown: the id is kept above
			}

			q.start = start(src, row);

			q.xp_rewards = new ArrayList<>();
			for (Level l : pairs(src, row, DBTableID.Quest.COL_STAT_XP_AWARDED))
			{
				Xp xp = new Xp();
				xp.skill_id = l.skill_id;
				xp.skill = l.skill;
				xp.xp = l.level;
				q.xp_rewards.add(xp);
			}

			q.unstarted_state = number(src.field(row, DBTableID.Quest.COL_UNSTARTEDSTATE, 0));
			q.end_state = number(src.field(row, DBTableID.Quest.COL_ENDSTATE, 0));
			q.recommendation_reason = text(src.field(row, DBTableID.Quest.COL_CR_RECOMMENDATION_REASON, 0));
			out.quests.add(q);
		}
		out.quest_count = out.quests.size();
		return out;
	}

	// ---------------------------------------------------------------------------------------------- pieces

	/** The start tile and NPCs. The coordinate is packed: x in bits 14-27, y in bits 0-13, plane above bit 28. */
	private static Start start(Source src, int row)
	{
		Integer packed = number(src.field(row, DBTableID.Quest.COL_STARTCOORD, 0));
		int[] npcs = ints(src.field(row, DBTableID.Quest.COL_STARTNPC, 0));
		if (packed == null && npcs.length == 0)
		{
			return null;
		}
		Start s = new Start();
		if (packed != null)
		{
			s.x = (packed >> 14) & 0x3FFF;
			s.y = packed & 0x3FFF;
			s.plane = (packed >>> 28) & 0x3;
		}
		s.npc_ids = new ArrayList<>();
		s.npc_names = new ArrayList<>();
		for (int npc : npcs)
		{
			s.npc_ids.add(npc);
			String npcName = src.npcName(npc);
			if (npcName != null && (npcName.trim().isEmpty() || "null".equalsIgnoreCase(npcName.trim())))
			{
				npcName = null; // the game's cache names some NPCs "null": that is an unknown name, not a name
			}
			s.npc_names.add(npcName);
		}
		return s;
	}

	private static boolean hasLetter(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (Character.isLetter(s.charAt(i)))
			{
				return true;
			}
		}
		return false;
	}

	/** A column holding two parts: the skill ids, then a number for each (a level, or an amount of experience). */
	private static List<Level> pairs(Source src, int row, int column)
	{
		int[] skills = ints(src.field(row, column, 0));
		int[] values = ints(src.field(row, column, 1));
		List<Level> out = new ArrayList<>();
		for (int i = 0; i < Math.min(skills.length, values.length); i++)
		{
			Level l = new Level();
			l.skill_id = skills[i];
			String skill = src.skillName(skills[i]);
			l.skill = skill != null ? skill : "skill#" + skills[i];
			l.level = values[i];
			out.add(l);
		}
		return out;
	}

	private static int[] ints(Object[] cell)
	{
		if (cell == null)
		{
			return new int[0];
		}
		int n = 0;
		for (Object o : cell)
		{
			if (o instanceof Number)
			{
				n++;
			}
		}
		int[] out = new int[n];
		int i = 0;
		for (Object o : cell)
		{
			if (o instanceof Number)
			{
				out[i++] = ((Number) o).intValue();
			}
		}
		return out;
	}

	private static Integer number(Object[] cell)
	{
		int[] v = ints(cell);
		return v.length == 0 ? null : v[0];
	}

	private static int orZero(Integer value)
	{
		return value == null ? 0 : value;
	}

	private static String text(Object[] cell)
	{
		if (cell == null || cell.length == 0 || !(cell[0] instanceof String))
		{
			return null;
		}
		String s = ((String) cell[0]).trim();
		return s.isEmpty() ? null : s;
	}

	// --------------------------------------------------------------------------------------------- json model

	@SuppressWarnings("unused")
	static class Export
	{
		String exported_at;
		int format_version;
		int client_revision;
		String source;
		String note;
		int quest_count;
		int skipped_placeholder_rows;
		List<Quest> quests;
	}

	@SuppressWarnings("unused")
	static class Quest
	{
		int row_id;
		Integer quest_id;
		String name;
		boolean members;
		Integer difficulty_code;
		Integer length_code;
		Integer quest_points;
		Integer series;
		Integer series_number;
		int[] release_date_parts;
		List<Level> levels;
		List<Level> recommended_levels;
		List<Integer> required_quest_rows;
		List<String> required_quests;
		Integer required_quest_points;
		Integer requirement_combat_raw;
		Integer prerequisite_direct;
		Integer prerequisite_indirect;
		Start start;
		List<Xp> xp_rewards;
		Integer unstarted_state;
		Integer end_state;
		String recommendation_reason;
	}

	@SuppressWarnings("unused")
	static class Level
	{
		int skill_id;
		String skill;
		int level;
	}

	@SuppressWarnings("unused")
	static class Xp
	{
		int skill_id;
		String skill;
		int xp;
	}

	@SuppressWarnings("unused")
	static class Start
	{
		int x;
		int y;
		int plane;
		List<Integer> npc_ids;
		List<String> npc_names;
	}
}

package com.gorsok.toolkitexporter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

// Each export can be switched off. The OSRS Toolkit app reads these same settings
// from the RuneLite profile to show which data is being exported.
@ConfigGroup(OsrsToolkitExporterConfig.GROUP)
public interface OsrsToolkitExporterConfig extends Config
{
	String GROUP = "osrstoolkitexporter";

	@ConfigItem(
			keyName = "exportPosition",
			name = "Export position",
			description = "Write your live world position to position.json",
			position = 1
	)
	default boolean exportPosition()
	{
		return true;
	}

	@ConfigItem(
			keyName = "exportGeOffers",
			name = "Export GE offers",
			description = "Write your Grand Exchange offers to ge_offers.json",
			position = 2
	)
	default boolean exportGeOffers()
	{
		return true;
	}

	@ConfigItem(
			keyName = "exportGameQuests",
			name = "Export game quest data",
			description = "Write the game's own quest table (requirements, start locations, experience rewards) to game_quests.json. Read from your client; nothing is sent anywhere",
			position = 3
	)
	default boolean exportGameQuests()
	{
		return false;
	}

	@ConfigItem(
			keyName = "exportCharacter",
			name = "Export character progress",
			description = "Write your levels and experience (character.json), quest states (quests.json), achievement diary tiers (diaries.json) and combat achievement totals (combat_achievements.json)",
			position = 4
	)
	default boolean exportCharacter()
	{
		return true;
	}

	@ConfigItem(
			keyName = "exportItems",
			name = "Export inventory and equipment",
			description = "Write your inventory (inventory.json) and worn equipment (equipment.json)",
			position = 5
	)
	default boolean exportItems()
	{
		return true;
	}

	@ConfigItem(
			keyName = "exportBank",
			name = "Export bank",
			description = "Write your bank (bank.json). It updates when you open your bank",
			position = 6
	)
	default boolean exportBank()
	{
		return true;
	}
}

package com.gorsok.toolkitexporter;

// OSRS Toolkit Exporter - part of the OSRS Toolkit suite (https://github.com/Gorsokk/osrs-toolkit).
// Each export can be switched on or off in the plugin's settings.
//
// What it does:
//   1) Position: every game tick, if your tile changed, writes
//        <home>/.runelite/plugin-data/position-exporter/<YourCharacterName>/position.json
//   2) Grand Exchange: whenever one of your 8 GE slots changes (new offer,
//      partial fill, completed, cancelled, collected), writes
//        <home>/.runelite/plugin-data/position-exporter/<YourCharacterName>/ge_offers.json
//      with every slot: item, buy/sell, state, offer price, qty filled / total,
//      gp spent, and the real average price paid/received.
//   3) Game quest data (off by default): once per login, writes the game's own Quest table
//      (levels and quests required, start tile and NPC, experience rewarded) to
//        <home>/.runelite/plugin-data/position-exporter/game_quests.json
//      It is read from your client, so it always matches the game version. See GameQuestData.
//   4) Character progress: levels and experience (character.json), the state of every quest of the game's
//      quest table (quests.json), achievement diary tiers (diaries.json) and combat achievement totals
//      (combat_achievements.json), in <home>/.runelite/plugin-data/position-exporter/<YourCharacterName>/.
//      Written at login, then when they change (at most every few seconds). See PlayerData.
//   5) Items: inventory.json and equipment.json when they change, bank.json when the bank is opened.
//
// The files live in RuneLite's data folder for this plugin (file I/O goes through RuneLite's
// Filepath API); the OSRS Toolkit app reads them there, together with Character Export's files.
// Nothing is written while logged out. Nothing is ever sent over the network.
// Data is collected on the client thread; the disk writes happen on a background thread.

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.ScriptID;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import com.google.inject.Provides;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Filepath;

@Slf4j
@PluginDescriptor(
		name = "OSRS Toolkit Exporter",
		internalName = "position-exporter",
		description = "OSRS Toolkit suite: writes your live position, Grand Exchange offers, levels, quests, diaries, items and (optionally) the game's quest data to local JSON files, each switchable in the settings",
		tags = {"export", "position", "location", "json", "grand exchange", "ge", "quests", "toolkit", "character", "bank"}
)
public class OsrsToolkitExporterPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OsrsToolkitExporterConfig config;

	@Inject
	private ItemManager itemManager;

	// RuneLite's shared background executor: keeps file I/O off the client thread.
	@Inject
	private ScheduledExecutorService executor;

	// RuneLite requires reusing the client's Gson instance (customized via newBuilder()).
	@Inject
	private Gson clientGson;

	private Gson gson;

	private WorldPoint lastWritten;

	// Set when a GE slot changes; the actual write happens on the next game tick
	// (the local player's name isn't always known yet when offers load at login).
	private boolean geDirty;

	// Set at login and when the quest export is switched on; cleared once the file is written. The table
	// may not be loaded in the very first ticks, so a few tries are made.
	private boolean questsDirty;
	private int questTries;

	// Character progress: levels change often (boosts), game variables change all the time. Changes only mark the
	// data dirty; it is written at most once every few ticks.
	private static final int STATS_EVERY_TICKS = 5;      // ~3 s
	private static final int PROGRESS_EVERY_TICKS = 50;  // ~30 s: the quest status of every quest is asked again
	private boolean statsDirty;
	private boolean progressDirty;
	private int ticksSinceStats;
	private int ticksSinceProgress;
	private boolean inventoryDirty;
	private boolean equipmentDirty;
	private boolean bankDirty;

	@Provides
	OsrsToolkitExporterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OsrsToolkitExporterConfig.class);
	}

	@Override
	protected void startUp()
	{
		gson = clientGson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
		lastWritten = null;
		// Export current offers right away if the plugin is enabled while logged in.
		geDirty = true;
		questsDirty = true;
		questTries = 0;
		markAllPlayerData();
	}

	@Override
	protected void shutDown()
	{
		lastWritten = null;
		geDirty = false;
		questsDirty = false;
		statsDirty = false;
		progressDirty = false;
		inventoryDirty = false;
		equipmentDirty = false;
		bankDirty = false;
	}

	private void markAllPlayerData()
	{
		statsDirty = true;
		progressDirty = true;
		ticksSinceStats = STATS_EVERY_TICKS;
		ticksSinceProgress = PROGRESS_EVERY_TICKS;
		inventoryDirty = true;
		equipmentDirty = true;
		bankDirty = true; // only written if the client has the bank (it does once the bank was opened this session)
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			geDirty = true;
			questsDirty = true;
			questTries = 0;
			markAllPlayerData();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!OsrsToolkitExporterConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("exportGameQuests".equals(event.getKey()))
		{
			questsDirty = true;
			questTries = 0;
		}
		else if ("exportCharacter".equals(event.getKey()) || "exportItems".equals(event.getKey())
			|| "exportBank".equals(event.getKey()))
		{
			markAllPlayerData();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		statsDirty = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		progressDirty = true;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.INV)
		{
			inventoryDirty = true;
		}
		else if (id == InventoryID.WORN)
		{
			equipmentDirty = true;
		}
		else if (id == InventoryID.BANK)
		{
			bankDirty = true;
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		geDirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}

		if (geDirty)
		{
			geDirty = false;
			if (config.exportGeOffers())
			{
				writeGeOffers(local.getName());
			}
		}

		if (questsDirty && config.exportGameQuests())
		{
			exportGameQuests();
		}

		exportPlayerData(local);

		if (!config.exportPosition())
		{
			lastWritten = null;
			return;
		}

		WorldPoint pos = local.getWorldLocation();
		if (pos == null || pos.equals(lastWritten))
		{
			return;
		}

		lastWritten = pos;
		writePosition(local.getName(), pos);
	}

	// ---------------------------------------------------------------- position

	private void writePosition(String playerName, WorldPoint pos)
	{
		PositionSnapshot snapshot = new PositionSnapshot();
		snapshot.exported_at = Instant.now().toString();
		snapshot.player_name = playerName;
		snapshot.world = client.getWorld();
		snapshot.plane = pos.getPlane();
		snapshot.x = pos.getX();
		snapshot.y = pos.getY();
		snapshot.region_id = pos.getRegionID();
		snapshot.region_x = pos.getRegionX();
		snapshot.region_y = pos.getRegionY();

		writeJson(playerName, "position.json", snapshot);
	}

	// ---------------------------------------------------------- grand exchange

	private void writeGeOffers(String playerName)
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}

		GeSnapshot snapshot = new GeSnapshot();
		snapshot.exported_at = Instant.now().toString();
		snapshot.player_name = playerName;
		snapshot.world = client.getWorld();
		snapshot.note = "price = offer price; avg_price = real average price (spent / quantity_filled). "
				+ "A BOUGHT/SOLD slot stays listed until it is collected.";

		List<GeSlot> slots = new ArrayList<>();
		for (int i = 0; i < offers.length; i++)
		{
			GrandExchangeOffer offer = offers[i];
			GeSlot slot = new GeSlot();
			slot.slot = i + 1; // 1-8, like in game

			GrandExchangeOfferState state = offer == null ? GrandExchangeOfferState.EMPTY : offer.getState();
			slot.state = state.name();

			if (offer == null || state == GrandExchangeOfferState.EMPTY)
			{
				snapshot.empty_slots++;
				slots.add(slot);
				continue;
			}

			slot.type = isBuy(state) ? "BUY" : "SELL";
			slot.item_id = offer.getItemId();
			slot.item_name = itemManager.getItemComposition(offer.getItemId()).getName();
			slot.price = (long) offer.getPrice();
			slot.quantity_filled = offer.getQuantitySold();
			slot.quantity_total = offer.getTotalQuantity();
			slot.spent = (long) offer.getSpent();
			slot.progress_pct = slot.quantity_total > 0
					? Math.round(1000.0 * slot.quantity_filled / slot.quantity_total) / 10.0
					: 0.0;
			if (slot.quantity_filled > 0)
			{
				slot.avg_price = Math.round(10.0 * slot.spent / slot.quantity_filled) / 10.0;
			}
			slot.complete = state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.SOLD;
			slot.cancelled = state == GrandExchangeOfferState.CANCELLED_BUY || state == GrandExchangeOfferState.CANCELLED_SELL;

			if (!slot.complete && !slot.cancelled)
			{
				if ("BUY".equals(slot.type))
				{
					// gp still locked in the offer
					snapshot.gp_locked_in_buys += (slot.quantity_total - slot.quantity_filled) * slot.price;
				}
				snapshot.active_offers++;
			}

			slots.add(slot);
		}

		snapshot.slots = slots;
		writeJson(playerName, "ge_offers.json", snapshot);
	}

	private static boolean isBuy(GrandExchangeOfferState state)
	{
		return state == GrandExchangeOfferState.BUYING
				|| state == GrandExchangeOfferState.BOUGHT
				|| state == GrandExchangeOfferState.CANCELLED_BUY;
	}

	// ---------------------------------------------------------------- game quest data

	private void exportGameQuests()
	{
		GameQuestData.Export data = GameQuestData.decode(
				new ClientQuestSource(client), Instant.now().toString(), client.getRevision());
		if (data.quest_count == 0)
		{
			// the table may not be loaded yet: try again on a later tick, a few times only
			if (++questTries >= 5)
			{
				questsDirty = false;
				log.debug("OSRS Toolkit Exporter: the quest table was not available");
			}
			return;
		}

		questsDirty = false;
		writeGameData("game_quests.json", data);
	}

	// ---------------------------------------------------------------- character progress and items

	private void exportPlayerData(Player local)
	{
		String name = local.getName();
		String now = Instant.now().toString();
		ticksSinceStats++;
		ticksSinceProgress++;

		if (config.exportCharacter())
		{
			if (statsDirty && ticksSinceStats >= STATS_EVERY_TICKS)
			{
				statsDirty = false;
				ticksSinceStats = 0;
				writeJson(name, "character.json", character(local, now));
			}
			if (progressDirty && ticksSinceProgress >= PROGRESS_EVERY_TICKS)
			{
				ticksSinceProgress = 0;
				PlayerData.Quests quests = PlayerData.quests(now, questRows(), this::questName, this::questStatus,
					client.getVarpValue(VarPlayerID.QP));
				// the quest table may not be loaded yet: keep the data dirty and try again later
				progressDirty = quests == null;
				if (quests != null)
				{
					writeJson(name, "quests.json", quests);
				}
				writeJson(name, "diaries.json", PlayerData.diaries(now, client::getVarbitValue));
				writeJson(name, "combat_achievements.json",
					PlayerData.combatAchievements(now, client::getVarpValue, client::getVarbitValue));
			}
		}

		if (config.exportItems())
		{
			if (inventoryDirty)
			{
				inventoryDirty = false;
				writeItems(name, now, "inventory", InventoryID.INV);
			}
			if (equipmentDirty)
			{
				equipmentDirty = false;
				writeItems(name, now, "equipment", InventoryID.WORN);
			}
		}

		if (config.exportBank() && bankDirty)
		{
			bankDirty = false;
			writeItems(name, now, "bank", InventoryID.BANK);
		}
	}

	private PlayerData.CharacterFile character(Player local, String now)
	{
		List<PlayerData.SkillValue> skills = new ArrayList<>();
		for (Skill skill : Skill.values())
		{
			if (!ClientQuestSource.isSkill(skill))
			{
				continue;
			}
			skills.add(new PlayerData.SkillValue(skill.getName(), client.getRealSkillLevel(skill),
				client.getBoostedSkillLevel(skill), client.getSkillExperience(skill)));
		}
		List<String> types = new ArrayList<>();
		for (WorldType type : client.getWorldType())
		{
			types.add(type.name());
		}
		return PlayerData.character(now, local.getName(), client.getWorld(), types, local.getCombatLevel(), skills);
	}

	private List<Integer> questRows()
	{
		try
		{
			return client.getDBTableRows(DBTableID.Quest.ID);
		}
		catch (RuntimeException e)
		{
			return null; // the table is not loaded (yet)
		}
	}

	private String questName(int row)
	{
		try
		{
			Object[] cell = client.getDBTableField(row, DBTableID.Quest.COL_DISPLAYNAME, 0);
			return cell != null && cell.length > 0 && cell[0] instanceof String ? (String) cell[0] : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	// The game's own quest status script takes the quest's row of the Quest table (RuneLite's Quest ids are these rows).
	private int questStatus(int row)
	{
		client.runScript(ScriptID.QUEST_STATUS_GET, row);
		return client.getIntStack()[0];
	}

	private void writeItems(String name, String now, String kind, int containerId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return; // e.g. the bank before it was opened this session: keep the last file
		}
		Item[] items = container.getItems();
		int[] ids = new int[items.length];
		int[] qtys = new int[items.length];
		for (int i = 0; i < items.length; i++)
		{
			ids[i] = items[i].getId();
			qtys[i] = items[i].getQuantity();
		}
		writeJson(name, kind + ".json", PlayerData.items(now, kind, ids, qtys,
			id -> itemManager.getItemComposition(id).getName()));
	}

	// ------------------------------------------------------------------ output

	private void writeJson(String playerName, String fileName, Object data)
	{
		// Serialize now (client thread, consistent snapshot), write later (background thread).
		final String json = gson.toJson(data);
		executor.execute(() -> writeFile(playerName, fileName, json));
	}

	// Game-wide data (not tied to a character) goes in the plugin's own folder, not in a character's.
	private void writeGameData(String fileName, Object data)
	{
		final String json = gson.toJson(data);
		executor.execute(() -> writeFile(null, fileName, json));
	}

	private void writeFile(String playerName, String fileName, String json)
	{
		try
		{
			// RuneLite's sandboxed data folder for this plugin: .runelite/plugin-data/position-exporter/
			Filepath dir = playerName == null ? getPluginDirectory() : getPluginDirectory().joinSegment(playerName);
			dir.createDirectories();
			Filepath outFile = dir.joinSegment(fileName);
			Filepath tmpFile = dir.joinSegment(fileName + ".tmp");

			// Write to a temp file then swap it in, so a reader never sees half a file.
			tmpFile.write(json.getBytes(StandardCharsets.UTF_8));
			try
			{
				tmpFile.moveTo(outFile, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (IOException atomicFailed)
			{
				tmpFile.moveTo(outFile, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException | IllegalArgumentException e)
		{
			log.warn("OSRS Toolkit Exporter: failed to write {}", fileName, e);
		}
	}

	// ------------------------------------------------------------- json models

	@SuppressWarnings("unused")
	private static class PositionSnapshot
	{
		String exported_at;
		String player_name;
		int world;
		int plane;
		int x;
		int y;
		int region_id;
		int region_x;
		int region_y;
	}

	@SuppressWarnings("unused")
	private static class GeSnapshot
	{
		String exported_at;
		String player_name;
		int world;
		int active_offers;
		int empty_slots;
		long gp_locked_in_buys;
		String note;
		List<GeSlot> slots;
	}

	@SuppressWarnings("unused")
	private static class GeSlot
	{
		int slot;
		String state;
		String type;
		Integer item_id;
		String item_name;
		Long price;
		Integer quantity_filled;
		Integer quantity_total;
		Long spent;
		Double avg_price;
		Double progress_pct;
		Boolean complete;
		Boolean cancelled;
	}
}

package com.gorsok.toolkitexporter;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * The player's own progress, as plain documented structures: levels, quest states, achievement diary tiers,
 * combat achievement totals, and the items of the inventory, equipment and bank.
 *
 * Everything comes from the running game client (skills, the game's quest table and its quest status script,
 * game variables, item containers). Nothing is fetched from anywhere and nothing is sent anywhere.
 *
 * Reading the client is kept out of this class (plain values and functions are passed in) so that it can be
 * tested on its own.
 */
final class PlayerData
{
	static final int FORMAT_VERSION = 1;
	static final String SOURCE = "OSRS Toolkit Exporter, read from the game client";

	private PlayerData()
	{
	}

	// ------------------------------------------------------------------ character

	static CharacterFile character(String exportedAt, String name, int world, List<String> worldTypes, int combatLevel,
		List<SkillValue> skills)
	{
		CharacterFile out = new CharacterFile();
		out.exported_at = exportedAt;
		out.format_version = FORMAT_VERSION;
		out.source = SOURCE;
		out.account_name = name;
		out.world = world;
		out.world_types = new ArrayList<>(worldTypes);
		out.combat_level = combatLevel;
		out.stats = new LinkedHashMap<>();
		for (SkillValue s : skills)
		{
			Stat st = new Stat();
			st.real_level = s.real;
			st.boosted_level = s.boosted;
			st.experience = s.xp;
			out.stats.put(s.name, st);
			out.total_level += s.real;
			out.total_experience += s.xp;
		}
		return out;
	}

	static final class SkillValue
	{
		final String name;
		final int real;
		final int boosted;
		final int xp;

		SkillValue(String name, int real, int boosted, int xp)
		{
			this.name = name;
			this.real = real;
			this.boosted = boosted;
			this.xp = xp;
		}
	}

	// --------------------------------------------------------------------- quests

	static final String FINISHED = "FINISHED";
	static final String IN_PROGRESS = "IN_PROGRESS";
	static final String NOT_STARTED = "NOT_STARTED";

	/** The game's quest status script answers 2 (finished), 1 (not started) or anything else (in progress). */
	static String questState(int status)
	{
		switch (status)
		{
			case 2:
				return FINISHED;
			case 1:
				return NOT_STARTED;
			default:
				return IN_PROGRESS;
		}
	}

	/**
	 * @param rows        the row ids of the game's Quest table (null: not loaded yet)
	 * @param nameOfRow   the quest's name for a row (null when unreadable)
	 * @param statusOfRow the game's quest status for a row (the row id is the quest id the status script takes)
	 * @param questPoints the player's quest points, from the game variable
	 * @return null when the table is not loaded yet
	 */
	static Quests quests(String exportedAt, List<Integer> rows, IntFunction<String> nameOfRow,
		IntUnaryOperator statusOfRow, int questPoints)
	{
		if (rows == null || rows.isEmpty())
		{
			return null;
		}
		Quests out = new Quests();
		out.exported_at = exportedAt;
		out.format_version = FORMAT_VERSION;
		out.source = SOURCE + " (the game's Quest table and its quest status script)";
		out.quest_points = questPoints;
		out.quests = new ArrayList<>();
		out.summary = new QuestSummary();
		for (int row : rows)
		{
			String name = nameOfRow.apply(row);
			if (name == null || !hasLetter(name))
			{
				continue; // unreadable, or a placeholder row (a quest called "."): not a quest yet
			}
			QuestState q = new QuestState();
			q.id = row;
			q.name = name;
			q.state = questState(statusOfRow.applyAsInt(row));
			out.quests.add(q);
			if (FINISHED.equals(q.state))
			{
				out.summary.finished++;
			}
			else if (NOT_STARTED.equals(q.state))
			{
				out.summary.not_started++;
			}
			else
			{
				out.summary.in_progress++;
			}
		}
		out.quests.sort((a, b) -> a.name.compareToIgnoreCase(b.name));
		return out;
	}

	static boolean hasLetter(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (Character.isLetter(s.charAt(i)))
			{
				return true;
			}
		}
		return false;
	}

	// -------------------------------------------------------------------- diaries

	static final String[] TIERS = {"easy", "medium", "hard", "elite"};

	/**
	 * Region name and the game variables (varbits) that say whether each tier (easy, medium, hard, elite) is done.
	 * Named game constants only (net.runelite.api.gameval.VarbitID).
	 */
	static final Object[][] DIARIES = {
		{"Ardougne", new int[]{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE,
			VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE}},
		{"Desert", new int[]{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE,
			VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE}},
		{"Falador", new int[]{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE,
			VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE}},
		{"Fremennik", new int[]{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE,
			VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE}},
		{"Kandarin", new int[]{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE}},
		// Karamja's first three tiers use other variables (ATJUN_*_DONE); read the same way, see the file's note.
		{"Karamja", new int[]{VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE,
			VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE}},
		{"Kourend & Kebos", new int[]{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE,
			VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE}},
		{"Lumbridge & Draynor", new int[]{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE,
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE}},
		{"Morytania", new int[]{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE,
			VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE}},
		{"Varrock", new int[]{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE,
			VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE}},
		{"Western Provinces", new int[]{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE,
			VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE}},
		{"Wilderness", new int[]{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE,
			VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE}},
	};

	static Diaries diaries(String exportedAt, IntUnaryOperator varbit)
	{
		Diaries out = new Diaries();
		out.exported_at = exportedAt;
		out.format_version = FORMAT_VERSION;
		out.source = SOURCE + " (game variables)";
		out.note = "complete = the game variable for the tier is not 0; value is that raw variable. Task-by-task progress "
			+ "is not exported. Karamja easy, medium and hard use different variables than the other diaries.";
		out.diaries = new LinkedHashMap<>();
		out.summary = new DiarySummary();
		for (Object[] d : DIARIES)
		{
			int[] ids = (int[]) d[1];
			Map<String, DiaryTier> tiers = new LinkedHashMap<>();
			for (int i = 0; i < TIERS.length; i++)
			{
				DiaryTier t = new DiaryTier();
				t.value = varbit.applyAsInt(ids[i]);
				t.complete = t.value != 0;
				tiers.put(TIERS[i], t);
				out.summary.tiers_possible++;
				if (t.complete)
				{
					out.summary.tiers_complete++;
				}
			}
			out.diaries.put((String) d[0], tiers);
		}
		return out;
	}

	// ------------------------------------------------------- combat achievements

	/** The game variables (varps) whose bits are the combat achievement tasks done (one bit per task). */
	static final int[] CA_TASK_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20,
	};

	static final String[] CA_TIERS = {"easy", "medium", "hard", "elite", "master", "grandmaster"};
	static final int[] CA_TIER_VARBITS = {
		VarbitID.CA_TIER_STATUS_EASY, VarbitID.CA_TIER_STATUS_MEDIUM, VarbitID.CA_TIER_STATUS_HARD,
		VarbitID.CA_TIER_STATUS_ELITE, VarbitID.CA_TIER_STATUS_MASTER, VarbitID.CA_TIER_STATUS_GRANDMASTER,
	};

	static CombatAchievements combatAchievements(String exportedAt, IntUnaryOperator varp, IntUnaryOperator varbit)
	{
		CombatAchievements out = new CombatAchievements();
		out.exported_at = exportedAt;
		out.format_version = FORMAT_VERSION;
		out.source = SOURCE + " (game variables)";
		out.note = "total_tasks_completed counts the task bits the game sets; points is the game's own count. "
			+ "tier_status_raw are the game's raw tier variables (meaning not decoded yet). Task names and per-tier "
			+ "counts are not exported yet.";
		out.summary = new CaSummary();
		for (int id : CA_TASK_VARPS)
		{
			out.summary.total_tasks_completed += Integer.bitCount(varp.applyAsInt(id));
		}
		out.summary.points = varbit.applyAsInt(VarbitID.CA_POINTS);
		out.summary.named_data_available = false;
		out.tier_status_raw = new LinkedHashMap<>();
		for (int i = 0; i < CA_TIERS.length; i++)
		{
			out.tier_status_raw.put(CA_TIERS[i], varbit.applyAsInt(CA_TIER_VARBITS[i]));
		}
		return out;
	}

	// ---------------------------------------------------------------------- items

	/**
	 * @param ids  item id per slot (-1 or less: empty)
	 * @param qtys quantity per slot (0 or less: empty, e.g. a bank placeholder)
	 */
	static Items items(String exportedAt, String kind, int[] ids, int[] qtys, IntFunction<String> nameOf)
	{
		Items out = new Items();
		out.exported_at = exportedAt;
		out.format_version = FORMAT_VERSION;
		out.source = SOURCE;
		out.kind = kind;
		out.items = new ArrayList<>();
		for (int slot = 0; slot < ids.length && slot < qtys.length; slot++)
		{
			if (ids[slot] < 0 || qtys[slot] <= 0)
			{
				continue;
			}
			Item it = new Item();
			it.slot = slot;
			it.id = ids[slot];
			it.quantity = qtys[slot];
			it.name = nameOf.apply(ids[slot]);
			out.items.add(it);
		}
		out.item_count = out.items.size();
		return out;
	}

	// ---------------------------------------------------------------- json models

	@SuppressWarnings("unused")
	static class CharacterFile
	{
		String exported_at;
		int format_version;
		String source;
		String account_name;
		int world;
		List<String> world_types;
		int combat_level;
